public class TextNodeTests {
    private String text;
    private Appendable output;

    @Test
    public void testIsBlank() {
        this.text = "   \n";
        Assert.assertTrue(TextNode.isBlank());
    }

    @Test
    public void testSplitText() {
        TextNode node1 = new TextNode("Hello World");
        TextNode node2 = node1.splitText(6);
        Assert.notNull(node2, "Expected a TextNode");
        Assert.notNull(node1, "Expected a TextNode");
        Assert.notSame(node1, node2);
    }

    @Test
    public void testClone() {
        TextNode node1 = new TextNode("Hello World");
        TextNode node2 = node1.clone();
        Assert.notNull(node1, "Expected a TextNode");
        Assert.notNull(node2, "Expected a TextNode");
        Assert.notSame(node1, node2);
    }

    @Test
    public void testToString() {
        this.text = "<p>This is a paragraph.</p>";
        Assert.assertEquals("This is a paragraph.", new String(TextNode.toString()));
    }

    @Before
    public void setup() {
        output = System.out;
    }

    @After
    public void tearDown() {
        System.out.flush();
    }

    @Test
    public void testNormaliseWhitespace() {
        Assert.assertEquals("   \n", TextNode.normaliseWhitespace("   "));
    }

    @Test
    public void testStripLeadingWhitespace() {
        StringBuilder sb = new StringBuilder();
        sb.append("   \n");
        Assert.assertEquals("  \n", TextNode.stripLeadingWhitespace(sb));
    }

    @Test
    public void testLastCharIsWhitespace() {
        StringBuilder sb = new StringBuilder();
        sb.append("a");
        Assert.assertTrue(TextNode.lastCharIsWhitespace(sb));
    }
